fun modPow(a: Long, e: Long): Long {
    var base = a % MOD
    var exp = e
    var result = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) {
            result = (result * base) % MOD
        }
        base = (base * base) % MOD
        exp = exp shr 1
    }
    return result
}

fun main() {
    val (k, va, vb) = readLine()!!.split(" ").map { it.toInt() }

    val den = modPow((va + vb).toLong(), MOD - 2)
